/**
 * Direct deployment script using viem — no hardhat required
 * Deploys ComputeRouter with our wallet as agent
 */

import { createWalletClient, createPublicClient, http, defineChain } from 'viem';
import { privateKeyToAccount } from 'viem/accounts';
import { readFileSync } from 'fs';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));

const PRIVATE_KEY = '0xbee08246ca39778e583dcc1cf32e005ac3da4a3c1da50e80c57060066a52fc8a';

const adiTestnet = defineChain({
  id: 99999,
  name: 'ADI Testnet',
  nativeCurrency: { name: 'ADI', symbol: 'ADI', decimals: 18 },
  rpcUrls: { default: { http: ['https://rpc.ab.testnet.adifoundation.ai'] } },
  testnet: true
});

// ComputeRouter bytecode - we'll compile it inline using solc
// For now, use the existing compiled artifact if available
const account = privateKeyToAccount(PRIVATE_KEY);
console.log('Deploying from:', account.address);

const walletClient = createWalletClient({
  account,
  chain: adiTestnet,
  transport: http()
});

const publicClient = createPublicClient({
  chain: adiTestnet,
  transport: http()
});

// Check balance first
const balance = await publicClient.getBalance({ address: account.address });
console.log('Balance:', balance.toString(), 'wei');

if (balance === 0n) {
  console.error('ERROR: Wallet has no ADI tokens. Please fund it first.');
  process.exit(1);
}

// ComputeRouter V2 bytecode (compiled from Solidity 0.8.28)
// This is a simple contract with:
// - No constructor parameters
// - submitJob() open to all
// - recordRoutingDecision() onlyAgent
// - setInitialAgent() to set agent once
const COMPUTE_ROUTER_BYTECODE = '';

// Actually let me use a simpler approach - write a proper script
console.log('Note: Direct bytecode deployment - checking for compiled artifacts...');

// Try to find compiled artifact
import { existsSync } from 'fs';

const artifactPaths = [
  resolve(__dirname, 'artifacts/contracts/ComputeRouter.sol/ComputeRouter.json'),
  resolve(__dirname, 'cache/artifacts/contracts/ComputeRouter.sol/ComputeRouter.json'),
];

let artifact = null;
for (const p of artifactPaths) {
  if (existsSync(p)) {
    artifact = JSON.parse(readFileSync(p, 'utf8'));
    console.log('Found artifact at:', p);
    break;
  }
}

if (!artifact) {
  console.error('No compiled artifact found. Need to compile first.');
  console.log('Run: cd hardhat && npm install && npx hardhat compile');
  process.exit(1);
}

console.log('Deploying ComputeRouter...');
const hash = await walletClient.deployContract({
  abi: artifact.abi,
  bytecode: artifact.bytecode,
  args: [],
});

console.log('Deploy tx hash:', hash);

const receipt = await publicClient.waitForTransactionReceipt({ hash });
console.log('✅ Contract deployed!');
console.log('Contract address:', receipt.contractAddress);
console.log('Block:', receipt.blockNumber.toString());
console.log('');
console.log('UPDATE THIS IN offchain/src/lib/contracts/compute-router.ts:');
console.log(`export const COMPUTE_ROUTER_ADDRESS = '${receipt.contractAddress}' as \`0x\${string}\``);
